            for (int i = 0; i < raw.Length; i++) raw[i] = sessionMap[raw[i]];
            return encoding.GetString(raw);
        }
        int legacyPage = encoding?.CodePage switch
        {
            1254 or 857 => 1254,
            1251 or 866 or 10007 => 1251,
            1253 or 737 or 10006 => 1253,
            _ => 0,
        };
        if (legacyPage != 0) return Convert(text, encoding, upper, legacyPage);
        return upper ? text.ToUpperInvariant() : text.ToLowerInvariant();
    }

